int evalRPN(const std::vector<std::string>& t) {
    std::stack<long long> st;
    for (const auto& s : t) {
        if (s == "+" || s == "-" || s == "*" || s == "/") {
            long long a = st.top(); st.pop();
            long long b = st.top(); st.pop();
            if (s == "+") st.push(a + b);
            else if (s == "-") st.push(a - b);
            else if (s == "*") st.push(a * b);
            else st.push(a / b);
        } else st.push(std::stoll(s));
    }
    return (int)st.top();
}

