class MyStack {
  std::queue<int> q_;                  // front of q_ = top of the stack
public:
  void push(int x) {                   // O(n): rotate the older elements behind x
    q_.push(x);
    for (size_t i = 1; i < q_.size(); ++i) { q_.push(q_.front()); q_.pop(); }
  }
  int pop() { int v = q_.front(); q_.pop(); return v; }
  int top() const { return q_.front(); }
  bool empty() const { return q_.empty(); }
};

