// + - * / on non-negative integers, no parentheses; '/' truncates toward zero.
// O(n) time, O(1) memory: instead of a stack keep the finished sum plus the last term.
int calculate(const std::string& s) {
  long long total = 0, last = 0, num = 0;
  char op = '+';                                   // operator that precedes `num`
  for (size_t i = 0; i <= s.size(); ++i) {
    char c = i < s.size() ? s[i] : '\0';
    if (std::isdigit(static_cast<unsigned char>(c))) { num = num * 10 + (c - '0'); continue; }
    if (c == ' ') continue;
    // c is an operator or the end of input: apply the pending operator to num
    switch (op) {
      case '+': total += last; last = num; break;
      case '-': total += last; last = -num; break;
      case '*': last *= num; break;                // binds to the previous term only
      case '/': last /= num; break;                // C++ '/' truncates toward zero
    }
    op = c;
    num = 0;
  }
  return static_cast<int>(total + last);
}

#include <cctype>
#include <string>

// + - * / and parentheses, non-negative integer literals, '/' truncates toward zero.
// Recursive descent:  expr := term (('+'|'-') term)*
//                     term := factor (('*'|'/') factor)*
//                     factor := number | '(' expr ')'
class Calculator {
  const std::string& s_;
  size_t i_ = 0;
  void skip() { while (i_ < s_.size() && s_[i_] == ' ') ++i_; }
  char peek() { skip(); return i_ < s_.size() ? s_[i_] : '\0'; }

  long long factor() {
    if (peek() == '(') {
      ++i_;                                   // '('
      long long v = expr();
      peek(); ++i_;                           // ')'
      return v;
    }
    long long v = 0;
    while (i_ < s_.size() && std::isdigit(static_cast<unsigned char>(s_[i_])))
      v = v * 10 + (s_[i_++] - '0');
    return v;
  }
  long long term() {
    long long v = factor();
    for (char c = peek(); c == '*' || c == '/'; c = peek()) {
      ++i_;
      long long r = factor();
      v = (c == '*') ? v * r : v / r;
    }
    return v;
  }
  long long expr() {
    long long v = term();
    for (char c = peek(); c == '+' || c == '-'; c = peek()) {
      ++i_;
      long long r = term();
      v = (c == '+') ? v + r : v - r;
    }
    return v;
  }
public:
  explicit Calculator(const std::string& s) : s_(s) {}
  int eval() { return static_cast<int>(expr()); }
};

int calculate(const std::string& s) { return Calculator(s).eval(); }

#include <string>
#include <vector>

std::string simplifyPath(const std::string& path) {
  std::vector<std::string> stack;            // vector as a stack: easy to join from the bottom
  size_t i = 0, n = path.size();
  while (i < n) {
    while (i < n && path[i] == '/') ++i;     // collapse any run of slashes
    size_t start = i;
    while (i < n && path[i] != '/') ++i;
    std::string part = path.substr(start, i - start);
    if (part.empty() || part == ".") continue;
    if (part == "..") {
      if (!stack.empty()) stack.pop_back();  // ".." at the root stays at the root
    } else {
      stack.push_back(part);                 // includes names like "..." or ".a"
    }
  }
  if (stack.empty()) return "/";
  std::string out;
  for (const auto& p : stack) out += "/" + p;
  return out;
}

